const item = $input.first();
const incoming = item.json || {};
const isHttp = incoming.entrypoint === 'http';
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : {};
const headers = incoming.headers && typeof incoming.headers === 'object' ? incoming.headers : {};
const suppliedKey = headers['x-excel-webhook-key'] ?? headers['X-Excel-Webhook-Key'] ?? '';
const expectedKey = typeof incoming.excel_webhook_api_key === 'string' ? incoming.excel_webhook_api_key : '';
const candidate = isHttp ? (incoming.session_id ?? body.session_id) : incoming.session_id;
const continuationSessionId = typeof candidate === 'string' ? candidate.trim() : '';
const hasFile = Boolean(item.binary?.file);
const parseRequest = (raw) => {
  if (raw && typeof raw === 'object' && !Array.isArray(raw)) return raw;
  if (typeof raw !== 'string' || !raw.trim()) return null;
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : { prompt: raw.trim() };
  } catch {
    return { prompt: raw.trim() };
  }
};
const binaryRequest = item.binary?.request
  ? parseRequest((await this.helpers.getBinaryDataBuffer(0, 'request')).toString('utf8'))
  : null;
const parsedPayload = parseRequest(body.payload);
const normalizedRequest = isHttp
  ? (parseRequest(incoming.request) ?? binaryRequest ?? parseRequest(parsedPayload?.request) ?? parseRequest(body.request) ?? (body.payload ? null : parseRequest(body)) ?? {})
  : (parseRequest(incoming.request) ?? (typeof incoming.prompt === 'string' ? { prompt: incoming.prompt } : {}));
const clarificationResponse = parseRequest(isHttp ? (incoming.clarification_response ?? body.clarification_response) : incoming.clarification_response);
return [{ json: {
  ...incoming,
  request: normalizedRequest,
  clarification_response: clarificationResponse,
  webhook_authorized: !isHttp || (Boolean(expectedKey) && suppliedKey === expectedKey),
  continuation_session_id: continuationSessionId,
  missing_input: !continuationSessionId && !hasFile,
}, binary: item.binary }];

return [{ json: {
  status: 'error',
  message: "New extraction requires multipart binary field 'file' (.xlsx/.xls); a clarification continuation requires session_id.",
  next_action: 'handle_error',
  data: { result_id: null, artifact_ref: null, columns: [], records: [], row_count: 0, returned_count: 0, truncated: false, provenance: [] },
  filters_applied: [], field_mapping: {}, assumptions: [], warnings: [],
  errors: [{ code: 'MISSING_INPUT', message: 'Provide file or session_id.' }], clarification: null, meta: { entrypoint: 'http' },
}}];

return [{ json: {
  status: 'error',
  message: 'Unauthorized webhook request.',
  next_action: 'handle_error',
  data: { result_id: null, artifact_ref: null, columns: [], records: [], row_count: 0, returned_count: 0, truncated: false, provenance: [] },
  filters_applied: [], field_mapping: {}, assumptions: [], warnings: [],
  errors: [{ code: 'UNAUTHORIZED', message: 'Provide a valid X-Excel-Webhook-Key header.' }], clarification: null, meta: { entrypoint: 'http' },
}}];

const item = $input.first();
const input = item.json || {};
const candidate = input.session_id;
const continuationSessionId = typeof candidate === 'string' ? candidate.trim() : '';
const hasFile = Boolean(item.binary?.file);
return [{
  json: {
    ...input,
    request: input.request ?? (input.prompt ? { prompt: input.prompt } : {}),
    clarification_response: input.clarification_response,
    continuation_session_id: continuationSessionId,
    missing_input: !continuationSessionId && !hasFile,
    webhook_authorized: true,
    entrypoint: 'subworkflow',
  },
  binary: item.binary,
}];

return [{ json: {
  status: 'error',
  message: "Sub-workflow input requires binary 'file' or session_id for a clarification continuation.",
  next_action: 'handle_error',
  data: { result_id: null, artifact_ref: null, columns: [], records: [], row_count: 0, returned_count: 0, truncated: false, provenance: [] },
  filters_applied: [], field_mapping: {}, assumptions: [], warnings: [],
  errors: [{ code: 'MISSING_INPUT', message: 'Pass binary.file or session_id.' }], clarification: null, meta: { entrypoint: 'subworkflow' },
}}];

const item = $input.first();
const value = item.json || {};
const parseObject = (raw, fallback = {}) => {
  if (raw === undefined || raw === null || raw === '') return fallback;
  if (typeof raw === 'object' && !Array.isArray(raw)) return raw;
  if (typeof raw === 'string') {
    try {
      const parsed = JSON.parse(raw);
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : fallback;
    } catch { return { prompt: raw }; }
  }
  return fallback;
};
const request = parseObject(value.request ?? value.body?.request ?? value.body, {});
const clarificationResponse = parseObject(value.clarification_response ?? value.body?.clarification_response, null);
const sessionId = typeof value.session_id === 'string' ? value.session_id.trim() : '';
if (!sessionId) throw new Error('Excel Tools did not provide session_id');
const continuation = Boolean(clarificationResponse);
return [{ json: {
  ...value,
  session_id: sessionId,
  request,
  clarification_response: clarificationResponse,
  is_clarification_continuation: continuation,
  agent_input: JSON.stringify({
    session_id: sessionId,
    request,
    continuation,
    clarification_response: clarificationResponse,
    instruction: continuation
      ? 'The user answered a clarification. First inspect get_session_state and continue from its resolved clarification and saved plan.'
      : 'This is a new workbook extraction. Follow the operating protocol exactly.'
  }),
}}];

const input = $input.first().json || {};
const prepared = $('Prepare AI Agent input').first().json;
const response = input.resolve_response ?? input;
const status = input.resolve_status_code ?? 0;
const detail = response?.detail || response?.error?.message || 'Could not resolve clarification.';
return [{json:{
 status:'error', message:'Could not resolve clarification.', next_action:'handle_error',
 data:{result_id:null,artifact_ref:null,columns:[],records:[],row_count:0,returned_count:0,truncated:false,provenance:[]},
 filters_applied:[],field_mapping:{},assumptions:[],warnings:[],
 errors:[{code:'CLARIFICATION_RESOLUTION_FAILED',message:String(detail),details:{http_status:status}}],clarification:null,
 meta:{session_id:prepared.session_id,entrypoint:prepared.entrypoint}
}}];

const state = $input.first().json || {};
const sessionId = state.session_id;
const entrypoint = $('Prepare AI Agent input').first().json.entrypoint;
const output = state.final_output;
if (output && typeof output === 'object') {
  return [{json:{...output, meta:{...(output.meta || {}), session_id:sessionId, entrypoint}}}];
}
return [{json:{
 status:'error', message:'AI agent ended without calling finalize_extraction.', next_action:'handle_error',
 data:{result_id:null,artifact_ref:null,columns:[],records:[],row_count:0,returned_count:0,truncated:false,provenance:[]},
 filters_applied:[],field_mapping:{},assumptions:[],warnings:[],
 errors:[{code:'AGENT_DID_NOT_FINALIZE',message:'No final_output was saved in the Excel session.'}],clarification:null,
 meta:{session_id:sessionId,entrypoint}
}}];

const sessionId = $('Prepare AI Agent input').first().json.session_id;
if (typeof sessionId !== 'string' || !sessionId) throw new Error('Missing session_id from agent input');
return [{ json: { ...$input.first().json, session_id: sessionId } }];

const state = $input.first().json || {};
const sessionId = state.session_id;
if (typeof sessionId !== 'string' || !sessionId) throw new Error('Missing session_id in Excel session state');
const final = state.final_output;
if (final && typeof final === 'object' && !Array.isArray(final)) return [{ json: { session_id: sessionId, final_args: final } }];
const zeroData = { result_id: null, artifact_ref: null, columns: [], records: [], row_count: 0, returned_count: 0, truncated: false, provenance: [] };
const base = {
  filters_applied: [], field_mapping: {},
  assumptions: Array.isArray(state.assumptions) ? state.assumptions : [],
  warnings: Array.isArray(state.warnings) ? state.warnings : [],
  meta: { session_id: sessionId, finalized_by: 'orchestrator_safety_net' },
};
const clarifications = Object.values(state.clarifications || {});
const pending = clarifications.find((item) => item && item.status === 'clarification_needed');
if (state.status === 'clarification_needed' && pending && typeof pending.token === 'string') {
  return [{ json: { session_id: sessionId, final_args: {
    ...base, status: 'clarification_needed',
    message: 'Additional information is required before extraction can continue.',
    next_action: 'ask_user', data: zeroData, errors: [],
    clarification: { token: pending.token, questions: pending.questions || [] },
  } } }];
}
const resultSets = Object.values(state.result_sets || {});
const result = resultSets[resultSets.length - 1];
// A query alone is never a terminal success: a server-side validation marker is
// persisted only by validate_result after its required columns/min_rows checks.
if (result && typeof result === 'object' && typeof result.result_id === 'string' && result.validation?.valid === true) {
  const artifacts = Object.values(state.artifacts || {});
  const artifact = artifacts[artifacts.length - 1];
  const table = (state.tables || {})[result.table_id] || {};
  const columns = Array.isArray(result.columns) ? result.columns : [];
  const records = Array.isArray(result.preview_records) ? result.preview_records : [];
  const rowCount = Number.isInteger(result.row_count) ? result.row_count : 0;
  const plan = state.plan && typeof state.plan === 'object' ? state.plan : {};
  return [{ json: { session_id: sessionId, final_args: {
    ...base, status: result.truncated ? 'partial' : 'success',
    message: artifact ? `Extraction completed; ${rowCount} matching row(s) exported.` : `Extraction completed; ${rowCount} matching row(s) found.`,
    next_action: artifact ? 'download_artifact' : 'none',
    data: { result_id: result.result_id, artifact_ref: artifact?.artifact_id || null, columns, records, row_count: rowCount, returned_count: records.length, truncated: Boolean(result.truncated), provenance: table.table_id ? [{ table_id: table.table_id, sheet: table.sheet, range: table.range }] : [] },
    filters_applied: Array.isArray(result.query?.filters) ? result.query.filters : (Array.isArray(plan.filters) ? plan.filters : []),
    field_mapping: plan.field_mapping && typeof plan.field_mapping === 'object' ? plan.field_mapping : {},
    errors: [], clarification: null,
  } } }];
}
const validationError = result && typeof result === 'object' && typeof result.result_id === 'string'
  ? { code: 'AGENT_RESULT_NOT_VALIDATED', message: `Result ${result.result_id} is missing a successful validate_result call.` }
  : { code: 'AGENT_DID_NOT_PRODUCE_RESULT', message: 'No saved query result is available.' };
return [{ json: { session_id: sessionId, final_args: {
  ...base, status: 'error', message: 'AI agent ended without a validated extraction result.',
  next_action: 'handle_error', data: zeroData, errors: [validationError], clarification: null,
} } }];

const prepared = $('Prepare AI Agent input').first().json || {};
const detected = $input.first().json?.result?.tables;
const tables = Array.isArray(detected) ? detected : [];
const request = prepared.request && typeof prepared.request === 'object' ? prepared.request : {};
const rawRequest = typeof request.prompt === 'string' ? request.prompt : JSON.stringify(request);
const normalized = rawRequest.toLocaleLowerCase().replace(/[\p{P}\p{S}_]+/gu, ' ');
const genericOnly = normalized
  .replace(/\b(extract|the|data|from|this|workbook|file|as|csv|xlsx|xls|excel|all|show|give|me|please|get|return)\b/giu, ' ')
  .replace(/\b(извлеки|извлечь|данные|из|этого|этой|этот|файла|файл|книги|книга|как|все|покажи|дай|мне|пожалуйста)\b/giu, ' ')
  .replace(/\s+/g, ' ')
  .trim();
const needsClarification = tables.length > 1 && genericOnly.length < 3;
const ranges = tables.map((table) => `${table.sheet || 'Sheet'}!${table.range || table.table_id || 'unknown'}`);
let agentPayload;
try { agentPayload = JSON.parse(prepared.agent_input); } catch { agentPayload = {}; }
agentPayload.preflight_tables = tables;
agentPayload.instruction = `${agentPayload.instruction || ''} Detected tables are already supplied in preflight_tables; use those IDs and do not call detect_tables again.`.trim();
return [{ json: {
  ...prepared,
  agent_input: JSON.stringify(agentPayload),
  preflight_needs_clarification: needsClarification,
  preflight_clarification_args: {
    questions: [{
      id: 'table_selection',
      type: 'text',
      question: `The workbook contains multiple independent tables (${ranges.join('; ')}). Which table should be extracted? Reply with its columns or range.`,
    }],
  },
} }];

const response = $input.first().json || {};
const prepared = $('Assess deterministic clarification need').first().json || {};
const result = response.result && typeof response.result === 'object' ? response.result : {};
const token = typeof result.token === 'string' ? result.token : '';
const questions = Array.isArray(result.questions) ? result.questions : [];
if (!token) throw new Error('Deterministic clarification was not persisted');
return [{ json: {
  status: 'clarification_needed',
  message: 'Additional information is required before extraction can continue.',
  next_action: 'ask_user',
  data: { result_id: null, artifact_ref: null, columns: [], records: [], row_count: 0, returned_count: 0, truncated: false, provenance: [] },
  filters_applied: [], field_mapping: {}, assumptions: [], warnings: [], errors: [],
  clarification: { token, questions },
  meta: { session_id: prepared.session_id, entrypoint: prepared.entrypoint, clarification_source: 'deterministic_preflight' },
} }];

const prepared = $('Prepare AI Agent input').first().json || {};
const resolution = $input.first().json || {};
return [{ json: {
  ...prepared,
  clarification_resolution: resolution.result ?? resolution,
  agent_input: prepared.agent_input,
} }];
